# Correct option and each distractor carry a reason, rather than a generic wrong-answer message.
drills=[
('paraphrase','Best paraphrase of “The team reduced delays by changing the schedule.”',('A revised timetable enabled the group to shorten waiting times.','Changes wording and structure while retaining action and result.'),[('The team reduced delays by changing the timetable.','Only one word changes; the original sentence frame is copied.'),('The new schedule removed every delay.','Reduced is weaker than removed every; this exaggerates the source.')]),
('paraphrase','Which is acceptable to retain unchanged in a paraphrase?',('A technical term such as “photosynthesis”.','Technical names often have no accurate substitute.'),[('The entire original sentence structure.','Independent structure is part of effective paraphrasing.'),('All descriptive phrases because they sound formal.','Formality does not justify copying distinctive wording.')]),
('paraphrase','Best rewrite of “Participation increased after the fee was removed.”',('Removing the charge was followed by greater participation.','Preserves sequence without claiming proven causation.'),[('Removing the charge certainly caused participation to double.','The source gives neither causation nor a doubling.'),('Participation decreased when the fee disappeared.','This reverses the meaning.')]),
('paraphrase','Which change uses a different word form?',('The team analysed the data → The team’s analysis of the data','Analysed is a verb; analysis is a noun.'),[('The team analysed → The group analysed','This changes a noun to a synonym, not its word class.'),('The team analysed → The team examined','Both analysed and examined are verbs.')]),
('paraphrase','Which version preserves “may improve access”?',('Could make access easier','Could preserves the possibility expressed by may.'),[('Will guarantee equal access','This turns a qualified possibility into certainty.'),('Has already improved every service','This introduces an observed past result and a broader claim.')]),
('summary','Best title for a passage about repairing devices before replacing them?',('Repair Before Replacement','Captures the central policy concisely.'),[('Computers','Too broad to express the passage’s main idea.'),('Why Everyone Must Stop Buying Devices','Adds an unsupported universal recommendation.')]),
('summary','Which detail should usually be omitted from a short summary?',('A minor example illustrating an already stated main idea','Examples can be removed while their general point is retained.'),[('The author’s central qualification','Removing it may distort the claim.'),('The main conclusion','It is normally essential to the text’s meaning.')]),
('summary','Which keywords best fit a summary of a supervised voluntary reading programme?',('voluntary reading; trained volunteers; participation','These identify purpose, delivery and evaluation.'),[('Saturday; blue chairs; page seven','Incidental details do not capture the main message.'),('amazing; perfect; wonderful','These are evaluations, not central concepts.')]),
('summary','Which sentence belongs in a neutral summary?',('The study compared responses before and after the change.','Reports the source without adding an opinion.'),[('I think the change was brilliant.','Adds a personal judgement.'),('Everyone should adopt this immediately.','Adds an unsupported recommendation.')]),
('summary','When should an explicit 20-word limit override “about half”?',('When the question specifies 20 words','The precise task instruction governs the answer.'),[('Never; half length is always compulsory','A general rule cannot override the given limit.'),('Only if the passage is boring','Interest is irrelevant to task requirements.')]),
('essay','Which is a defensible thesis?',('Colleges should offer peer tutoring with training and teacher supervision.','Takes a specific position that can be argued.'),[('Peer tutoring is a topic.','Names a topic without an arguable claim.'),('There are students in colleges.','A general fact does not establish a position.')]),
('essay','Which is a topic sentence for one body paragraph?',('Peer tutoring can make help more accessible to isolated students.','Introduces one supporting argument.'),[('This essay will discuss many things.','Too vague to guide a paragraph.'),('In conclusion, tutoring deserves support.','Signals a whole-essay conclusion.')]),
('essay','Identify a counter-argument to allowing AI during preparation.',('Students may submit generated text without understanding it.','Presents a reasonable objection to the thesis.'),[('Students can request clearer explanations.','Supports the case for assistance.'),('Assignments have deadlines.','Does not directly oppose the proposed policy.')]),
('essay','Which is a rebuttal to “Peer tutors can make mistakes”?',('Training and referral to teachers can reduce the risk of inaccurate explanations.','Acknowledges and addresses the concern with a mechanism.'),[('Anyone who disagrees is foolish.','Attacks people rather than the objection.'),('Peer tutoring is popular.','Popularity does not answer the accuracy concern.')]),
('essay','What should an essay conclusion do?',('Synthesize the reasons and restate the position','Closes the argument using points already developed.'),[('Introduce a third major argument','A new argument needs development in the body.'),('Copy the introduction word for word','Repetition is weaker than synthesis.')]),
('style','Best transition for an opposing view?',('However','Signals contrast.'),[('Furthermore','Signals addition, not opposition.'),('Consequently','Signals a result, not simply contrast.')]),
('style','Choose the logical linker: “The device was unsafe. ___, it was withdrawn.”',('Therefore','Withdrawal follows from the safety problem.'),[('Similarly','No parallel case is being compared.'),('Nevertheless','Would imply withdrawal despite the preceding fact.')]),
('style','Best academic alternative to “a lot of problems”?',('Numerous difficulties','Precise formal wording fits the meaning.'),[('Infinite disasters','Exaggerates both number and severity.'),('Tiny inconveniences','Changes the intended meaning and scale.')]),
('style','Which sentence avoids inflated vocabulary?',('The team used a short survey.','Direct and precise language is appropriate.'),[('The team operationalised an interrogative instrumentality.','Unnecessary complexity obscures a simple action.'),('The team did stuff.','Too vague for academic communication.')]),
('style','Which is a cautious interpretation?',('The findings suggest a possible association.','Matches uncertainty rather than claiming proof.'),[('The findings prove this always happens.','Universal certainty requires much stronger evidence.'),('The findings are totally awesome.','Informal personal evaluation is inappropriate.')]),
('email','Most appropriate request to a new professional contact?',('Could you please share the eligibility requirements?','Specific, courteous and actionable.'),[('Send details now!!!','Demanding punctuation and tone weaken professionalism.'),('Hey buddy, fix me a job.','Assumes familiarity and asks for an inappropriate guarantee.')]),
('email','Best subject for a replacement request?',('Replacement request: damaged monitor, order MON-284','States action, issue and identifying reference.'),[('URGENT!!!!','Gives no useful context.'),('Hello','Does not identify the purpose.')]),
('email','Best opening after a formal greeting?',('I am writing to request a replacement for order MON-284.','Places the purpose first.'),[('Since childhood, I have liked technology.','Irrelevant background delays the request.'),('Guess what happened!','Uses an informal conversational register.')]),
('email','Correct email sequence?',('Subject → greeting → purpose → details → request → polite close → signature','Moves from identification to context and action.'),[('Signature → details → subject → greeting','Places key components in an unhelpful order.'),('Request → signature → greeting → subject','A greeting and subject should frame the message first.')]),
('email','Best response when apologising for your own delay?',('I apologise for the delay and will set an earlier checking deadline.','Accepts responsibility and offers a preventive measure.'),[('It is entirely your fault for expecting it on time.','Shifts blame instead of addressing the delay.'),('Sorry lol.','Too casual and gives no practical response.')]),
('graph','Attendance rose from 80 to 100. Which is correct?',('Attendance rose by 20 to 100.','By states the change; to states the endpoint.'),[('Attendance rose by 100 to 20.','Swaps the amount and the endpoint.'),('Attendance rose at 20.','At does not describe the size of this change.')]),
('graph','Which preposition fits “Traffic peaked ___ 600 vehicles”?',('at','At introduces the value at the peak.'),[('by','By describes an amount of change.'),('to','To marks an endpoint after verbs such as rose, not peaked.')]),
('graph','A rate increases from 40% to 50%. What is the absolute gap?',('10 percentage points','Subtract percentages to get a percentage-point gap.'),[('10% relative growth','Relative growth is 10/40 = 25%.'),('50 percentage points','50% is the endpoint, not the change.')]),
('graph','The question asks only for a comparison. What should you avoid?',('Inventing reasons for the differences','Causes are not supplied or requested.'),[('Stating the largest difference','This is directly relevant to comparison.'),('Using units','Units make numerical statements meaningful.')]),
('graph','Which statement avoids confusing groups with time?',('Year 3 respondents preferred digital more often than Year 1 respondents.','Compares groups without claiming individual change.'),[('Every student changed from print to digital over time.','The chart does not track the same individuals.'),('Digital use certainly causes progression.','No causal relationship is established.')]),
('questionnaire','Which is open-ended?',('What difficulties do you face when using the portal?','Invites an unrestricted description.'),[('Do you use the portal? Yes / No.','A fixed yes/no response is closed.'),('Choose a rating from 1 to 5.','A fixed rating scale is closed.')]),
('questionnaire','Which is a neutral closed question?',('How clear are the signs? Very clear / Clear / Neutral / Unclear / Very unclear.','Provides balanced response choices.'),[('Why are the terrible signs so confusing?','Loaded wording assumes a negative judgement.'),('How helpful and attractive are the signs?','Combines two attributes in one question.')]),
('questionnaire','What is wrong with “Is the shuttle cheap and reliable?”',('It is double-barrelled.','Cost and reliability can receive different answers.'),[('It is necessarily open-ended.','It asks for a restricted judgement.'),('It contains a methodology section.','No research method is described.')]),
('questionnaire','What is wrong with “Do you agree our excellent portal saves time?”',('It is leading.','Excellent suggests the desired answer.'),[('It is perfectly neutral.','The evaluative adjective creates bias.'),('It asks for too much narrative detail.','Its main defect is bias, not narrative length.')]),
('questionnaire','What must Q2B contain in the upcoming exam?',('Exactly four open and four closed questions','Eight questions at half a mark each total four marks.'),[('At least ten open questions','Violates the specified composition.'),('Any eight questions, all yes/no if convenient','The balance of open and closed is mandatory.')]),
('abstracts','Which abstract sentence states purpose?',('This study aimed to compare two reminder formats.','States the research objective.'),[('Sixty patients completed a survey.','Describes methodology.'),('Fifty-two understood both messages.','Reports a result.')]),
('abstracts','Which sentence states methodology?',('Researchers interviewed 18 employees and analysed meeting notes.','Explains how evidence was gathered and analysed.'),[('Hybrid meetings can exclude remote staff.','Provides context or a problem.'),('Better audio may improve participation.','Suggests an implication.')]),
('abstracts','Which sentence is a result?',('Completion increased from 60% to 75% in the sample.','Reports a measured outcome.'),[('The aim was to assess completion.','States purpose.'),('Participants completed two exercises.','Describes a procedure unless presented as an outcome.')]),
('abstracts','What should you type for “write out the statement of purpose”?',('The exact purpose sentence or sentences from the abstract','The exam asks for the text, not its label.'),[('Purpose','Merely repeats the component name.'),('B','A letter alone does not satisfy write out.')]),
('abstracts','Can a sentence express both purpose and method?',('Yes; select it where it fulfils the named function.','Moves can overlap within a sentence.'),[('No; every sentence must have exactly one role.','Real abstracts do not follow that restriction.'),('Yes, so the abstract has no interpretable structure.','Overlap does not prevent reasoned identification.')]),
('report','Where should “18 of 30 students reported noise” appear?',('Findings','Reports observed evidence.'),[('Recommendations','A recommendation proposes action.'),('Title only','A title cannot replace an evidence section.')]),
('report','Where should “The manager should relocate the display within two weeks” appear?',('Recommendations','Assigns an actionable response and deadline.'),[('Methodology','It proposes future action rather than describing data collection.'),('Findings','It is not an observed result.')]),
('report','Which is a conclusion rather than a finding?',('The current signs do not consistently guide users to quiet areas.','Interprets the observed pattern.'),[('Six conversations were recorded near the entrance.','A direct observation belongs in findings.'),('Interview 20 users tomorrow.','This is a proposed action or future method.')]),
('report','What belongs in an executive summary?',('Purpose, method, main findings and recommended direction','Summarises the whole investigation.'),[('Only background, with no outcome','That is closer to an introduction.'),('A new result absent from the report','A summary cannot introduce unsupported evidence.')]),
('grammar','Choose the correct sentence.',('Each response was checked carefully.','Each response is singular; carefully modifies checked.'),[('Each response were checked careful.','Both agreement and adverb form are wrong.'),('Each responses was checked carefully.','Each requires a singular count noun.')]),
('grammar','Choose the correct article.',('a useful guide; an hour','Article choice follows sound: /y/ is consonantal; hour starts with a vowel sound.'),[('an useful guide; a hour','Both article choices follow letters rather than sounds.'),('an useful guide; an hour','Useful starts with the consonant sound /y/.')]),
('grammar','Repair “The device failed, we replaced it.”',('The device failed, so we replaced it.','So joins the two independent clauses.'),[('The device failed we replaced it.','Removing the comma creates a run-on.'),('Because the device failed.','Leaves an incomplete dependent-clause fragment.')]),
('grammar','Correct “We discussed about the report.”',('We discussed the report.','Discuss takes a direct object.'),[('We discussed on the report.','On is also unnecessary here.'),('We discussion the report.','The sentence needs a verb, not a noun.')]),
('grammar','Which is correct?',('The information is useful.','Information is uncountable and takes a singular verb.'),[('The informations are useful.','Information has no regular plural in this sense.'),('The information are useful.','The verb should agree with the uncountable noun.')]),
('grammar','Which version preserves a consistent past narrative?',('Yesterday, the team met and reviewed the plan.','Both events are placed in the established past time.'),[('Yesterday, the team meets and reviewed the plan.','Meets conflicts with yesterday and reviewed.'),('Yesterday, the team meeting and review the plan.','Neither verb form creates the required past clause.')])]
for n,(topic,p,correct,wrong) in enumerate(drills):
 options=[correct]+wrong;rotate=n%len(options);options=options[rotate:]+options[:rotate]
 opts=[dict(id=chr(97+i),text=t,explanation=e) for i,(t,e) in enumerate(options)]
 original.append(dict(id=f'wp-drill-{n+1:02}',subject='wp',topic=topic,title=p,source='Original fast drill',difficulty='Foundation',pool='original',type='mcq',partLabel='Drill',marks=1,suggestedMinutes=1,prompt=p,options=opts,answer=next(o['id'] for o in opts if o['text']==correct[0])))
match_sets=[
('abstracts','Identify abstract moves',['Background','Purpose','Methodology','Results'],[('Late arrivals disrupt clinics.','Background','Sets the problem context.'),('The aim was to test reminder clarity.','Purpose','States the study objective.'),('We surveyed 60 patients.','Methodology','Names the procedure and sample.'),('Fifty-two understood the message.','Results','Reports the measured outcome.')]),
('report','Place each report sentence',['Introduction','Methodology','Findings','Conclusion','Recommendations'],[('This report investigates library noise.','Introduction','Introduces purpose and scope.'),('Thirty students were interviewed.','Methodology','Describes evidence collection.'),('Eighteen reported disruption.','Findings','States observed evidence.'),('Current arrangements are insufficient.','Conclusion','Interprets the evidence.'),('Move signs within two weeks.','Recommendations','Proposes specific action.')]),
('questionnaire','Classify question formats',['Open','Yes/no','Multiple choice','Likert'],[('What would improve the service?','Open','Allows unrestricted responses.'),('Did you use it? Yes / No.','Yes/no','Two fixed responses.'),('Main device? Phone / Laptop / Tablet / Other.','Multiple choice','Select one category.'),('Rate agreement: strongly disagree to strongly agree.','Likert','An ordered agreement scale.')]),
('questionnaire','Identify questionnaire defects',['Leading','Double-barrelled','Ambiguous','Neutral'],[('Do you support our excellent initiative?','Leading','Excellent signals the preferred answer.'),('Is the service cheap and reliable?','Double-barrelled','Cost and reliability may differ.'),('Do you use it often?','Ambiguous','Often has no defined time frame.'),('How many journeys last week? 0 / 1–2 / 3 or more.','Neutral','A defined period and non-overlapping choices.')]),
('graph','Match trend functions',['Change','Endpoint','Peak','Starting point'],[('rose BY 20','Change','By gives the size of an increase.'),('increased TO 100','Endpoint','To states the resulting value.'),('peaked AT 120','Peak','At introduces the maximum value.'),('fell FROM 80','Starting point','From gives the initial value.')]),
('email','Identify email parts',['Subject','Salutation','Purpose','Request','Sign-off'],[('Replacement request: order 24','Subject','Identifies the topic in the inbox.'),('Dear Support Team,','Salutation','Addresses the recipient.'),('I am writing about a damaged item.','Purpose','Explains why the sender is writing.'),('Could you arrange a replacement?','Request','States the desired action.'),('Kind regards, Asha Rao','Sign-off','Closes and identifies the sender.')]),
('essay','Identify argument functions',['Thesis','Support','Counter-argument','Rebuttal'],[('Colleges should provide supervised peer tutoring.','Thesis','States the overall position.'),('Small groups let learners ask individual questions.','Support','Gives a reason for that position.'),('Peers may pass on errors.','Counter-argument','Raises a reasonable objection.'),('Training and referrals can limit this risk.','Rebuttal','Answers the objection.')]),
('style','Match transitions',['Addition','Contrast','Result','Example'],[('Furthermore','Addition','Adds another supporting point.'),('However','Contrast','Signals a contrasting idea.'),('Consequently','Result','Introduces an outcome.'),('For instance','Example','Introduces an illustration.')]),
('grammar','Match corrections to rules',['Agreement','Article','Adverb','Preposition'],[('Each response WERE → WAS','Agreement','Each response is singular.'),('AN useful guide → A useful guide','Article','Useful begins with a consonant sound.'),('spoke POLITE → POLITELY','Adverb','An adverb modifies spoke.'),('IN Monday → ON Monday','Preposition','Use on with named days.')]),
('style','Choose contextual academic vocabulary',['obtain','indicate','reduce','objective'],[('Acquire data = ___ data','obtain','Obtain means acquire; it does not imply invention.'),('The figures suggest = the figures ___','indicate','Indicate fits a cautious evidential claim.'),('Decrease unnecessary waste = ___ it','reduce','Reduce preserves the direction of change.'),('An impartial report = an ___ report','objective','Objective describes absence of personal bias.')])]
for n,(topic,title,cats,items) in enumerate(match_sets):
 original.append(dict(id=f'wp-match-{n+1:02}',subject='wp',topic=topic,title=title,source='Original fast drill',difficulty='Foundation',pool='original',type='match',partLabel='Drill',marks=len(items),suggestedMinutes=3,prompt='Choose the best category for every item. Categories may be used more than once.',categories=cats,items=[dict(id=f'i{i+1}',text=t,answer=a,explanation=e) for i,(t,a,e) in enumerate(items)]))
